column1:
CREATE TABLE IF NOT EXISTS device_sequences (
    id uuid NOT NULL DEFAULT gen_random_uuid(),
    device_code text NOT NULL,
    doc_type text NOT NULL,
    last_sequence integer DEFAULT 0
);

CREATE TABLE IF NOT EXISTS v_last_invoice_activity (
    invoice_id uuid,
    invoice_number text,
    status text,
    last_activity_at timestamp with time zone
);

CREATE TABLE IF NOT EXISTS v_last_project_activity (
    project_id uuid,
    project_code text,
    project_name character varying,
    last_activity_at timestamp with time zone
);

CREATE TABLE IF NOT EXISTS v_last_quotation_activity (
    quotation_id uuid,
    quotation_number text,
    status text,
    last_activity_at timestamp with time zone
);
